B.a9U=new A.ap(B.i6,["So remember Me; I will remember you.","Surah Al-Baqarah 2:152","\u0641\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u0650\u064a \u0623\u064e\u0630\u0652\u0643\u064f\u0631\u0652\u0643\u064f\u0645\u0652"],t.l)
B.a9T=new A.ap(B.i6,["Verily, Allah is with the patient.","Surah Al-Baqarah 2:153","\u0625\u0650\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0635\u064e\u0651\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e"],t.l)
B.a9S=new A.ap(B.i6,["And Allah is the best of planners.","Surah Al-Anfal 8:30","\u0648\u064e\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u0645\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e"],t.l)
